import numpy as np


def _w(seed, d):
    r = np.random.default_rng(seed)
    return [r.normal(size=(d, d)) * 0.5 for _ in range(4)]


def _x(seed, T, d):
    return np.random.default_rng(seed + 100).normal(size=(T, d))


def _prefix_unchanged():
    Wq, Wk, Wv, Wo = _w(3, 4)
    x = _x(3, 5, 4)
    y = x.copy()
    y[-1] = [9.0, -9.0, 9.0, -9.0]
    a = causal_self_attention(x, Wq, Wk, Wv, Wo, 2)
    b = causal_self_attention(y, Wq, Wk, Wv, Wo, 2)
    return bool(np.allclose(a[:-1], b[:-1], atol=1e-12)) and not bool(np.allclose(a[-1], b[-1]))
